The pattern: hollow boxes (rectangles of a non-background color) get their interior filled with a new color (7 in the demo).

```python
def transform(grid):
    from collections import Counter
    cnt = Counter(v for row in grid for v in row)
    bg = cnt.most_common(1)[0][0]
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # find bounding boxes per non-bg color
    boxes = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != bg:
                if v not in boxes:
                    boxes[v] = [r, r, c, c]
                else:
                    b = boxes[v]
                    b[0] = min(b[0], r); b[1] = max(b[1], r)
                    b[2] = min(b[2], c); b[3] = max(b[3], c)
    fill = 7
    for v, (r0, r1, c0, c1) in boxes.items():
        for r in range(r0 + 1, r1):
            for c in range(c0 + 1, c1):
                out[r][c] = fill
    return out
